head.script:
scwin.screenId = "jldinf20000";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 진입 파라미터 기본값 (회신표 entry_defaults — 전달분 우선). 진입점이 부르는 초기화 단계.
/**
 * @method
 * @name scwin.init_entryDefaults
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_entryDefaults = function () {
    let __pc_gubunRadio = $c.util.getComponent('dma_DownloadReq');
    if (!__pc_gubunRadio || typeof __pc_gubunRadio.get !== 'function') {
        console.warn('[sdd] entry_defaults 대상 부재: dma_DownloadReq');
    } else if (($c.data.getParameter('gubunRadio') == null || $c.data.getParameter('gubunRadio') === '') && (__pc_gubunRadio.get('gubunRadio') == null || __pc_gubunRadio.get('gubunRadio') === '')) {
        __pc_gubunRadio.set('gubunRadio', "1");
    }
};

// 속성 EL 실현 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_attrReals
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_attrReals = function () {
    let __attrReals = [{ childId: "ul_186", attr: "__html", fn: function () { return ([String($c.data.readValue("dma_page", "total", { silent: true })), String($c.data.readValue("dma_page", "currentPage", { silent: true })), String($c.data.readValue("dma_page", "pageCount", { silent: true }))].some(function (__v) { return String(__v == null ? '' : __v).trim() !== ''; }) ? ("총 <strong id=\"totPage\">" + String($c.data.readValue("dma_page", "total", { silent: true })) + "</strong>건 <span id=\"totPage1\">(" + String($c.data.readValue("dma_page", "currentPage", { silent: true })) + "/" + String($c.data.readValue("dma_page", "pageCount", { silent: true })) + ")</span>") : ''); } }];
    $c.util.applyAttrReals(__attrReals);
};

// 런타임 분기 평가 — 공용 $c.util.evalConds (화면은 조건 바인딩 목록만 보유)
// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = function () {
    let binds = [{ id: "c_otherwise_54", fn: function(){ return (!(($c.data.readValue("dma_pageContext", "thisServer", { ctx: true, label: "thisServer" }) === 'dr1') || ($c.data.readValue("dma_pageContext", "thisServer", { ctx: true, label: "thisServer" }) === 'dr2') || ($c.data.readValue("dma_pageContext", "thisServer", { ctx: true, label: "thisServer" }) === 'real1') || ($c.data.readValue("dma_pageContext", "thisServer", { ctx: true, label: "thisServer" }) === 'real2'))); } }, { id: "if_result", fn: function(){ return (!(String(($c.data.readValue("dma_pageContext", "result", { ctx: true, label: "result" })) == null ? '' : ($c.data.readValue("dma_pageContext", "result", { ctx: true, label: "result" }))).length === 0)); } }];
    $c.util.evalConds(binds);
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = function () {
    let __rowCopies = [{ childId: "ipt_curSh", fn: function () { return String(String($c.data.readValue("dma_pageContext", "curSh", { silent: true }))); } },
        { childId: "ipt_isurNm1", fn: function () { return String(String($c.data.readValue("dma_pageContext", "isurNm", { silent: true }))); } },
        { childId: "ipt_stdCdFind", fn: function () { return String(String($c.data.readValue("dma_pageContext", "stdcdfind", { silent: true }))); } },
        { childId: "ipt_comNm1", fn: function () { return String(String($c.data.readValue("dma_pageContext", "comNm", { silent: true }))); } },
        { childId: "ipt_isurCd1", fn: function () { return String(String($c.data.readValue("dma_pageContext", "isurCd", { silent: true }))); } },
        { childId: "cal_stdCdGrntStartDd", fn: function () { return String(String($c.data.readValue("dma_pageContext", "stdCdGrntStartDd", { silent: true }))); } },
        { childId: "cal_stdCdGrntEndDd", fn: function () { return String(String($c.data.readValue("dma_pageContext", "stdCdGrntEndDd", { silent: true }))); } }];
    $c.data.copyRows(__rowCopies);
};

/**
 * @method
 * @name scwin.init_datefmt_cal_stdCdGrntStartDd
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_stdCdGrntStartDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntStartDd", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_datefmt_cal_stdCdGrntEndDd
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_datefmt_cal_stdCdGrntEndDd = function () { $c.date.checkCalendarFormat("cal_stdCdGrntEndDd", "yyyyMMdd"); };

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        let pageIndex = $c.util.getComponent('ipt_currentPage').getValue();
        let pageObj = $('.paging td:contains(' + pageIndex + ')');
        let pagingLeng = $('.paging td:contains(' + pageIndex + ')').length;
        for (let i = 0; i < pagingLeng; i++) {
            let obj = pageObj[i];
            let val = $(obj).text();
            if (pageIndex !== val) {
                continue;
            }
            let font = "<font color='blue'>" + val + "</font>";
            $(obj).html(font);
            $(obj).attr("style", "font-size:15px;");
        }
        scwin.dateSetting();
        $('input[name=ipt_isurNm1]').keypress(async function(e) {
                if (e.keyCode === 13) {
                    await scwin.fn_search('1');
                }
        });
        $('input[name=searchRadio]').bind("click", function() {
                $c.util.getComponent('ipt_curSh').setValue($(this).val());
                $('.paging').empty();
                let resetPaging = "<tr><td style='padding-left:5px'><img diabled src='/img/btn/btn-pprev.gif' alt=''></td><td style='padding-left:5px'><img src='/img/btn/btn-prev.gif' alt='' ></td><td class='bg_pagingbar'></td><td>1</td><td style='padding-left:5px'><img src='/img/btn/btn-next.gif' border='0' ></td><td style='padding-left:5px'><img src='/img/btn/btn-nnext.gif' alt='' ></a></td></tr>";
                $('.paging').append(resetPaging);
        });
        $c.util.getComponent("ipt_isurNm1").focus();
        let gubunRadio = (String(($c.data.readValue("dma_pageContext", "gubunRadio", { ctx: true, soft: true, label: "gubunRadio" })) == null ? '' : ($c.data.readValue("dma_pageContext", "gubunRadio", { ctx: true, soft: true, label: "gubunRadio" }))).indexOf('$' + '{') >= 0 ? '' : String(($c.data.readValue("dma_pageContext", "gubunRadio", { ctx: true, soft: true, label: "gubunRadio" })) == null ? '' : ($c.data.readValue("dma_pageContext", "gubunRadio", { ctx: true, soft: true, label: "gubunRadio" }))));
        if (gubunRadio === '') {
            scwin.fn_appDate2('stdCdGrntStartDd', 'stdCdGrntEndDd', 12);
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf20000.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 공용 $c.data.recvParamData (§106, 이름 고정 "paramData"; 실패 표출은 gcc 함수 몫). onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { $c.data.recvParamData('dma_pageContext'); };

scwin.dmenus = undefined; try { scwin.dmenus = {
        "bmenu":4
        ,"mmenu":0
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldinf20000' }); }

// as-is 흐름 보존 — 스켈레톤이 대체한 함수가 쓰던 전역 선언
scwin._popupWindow = undefined; scwin.type = undefined;

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_conds();
        scwin.init_entryDefaults();
        scwin.init_datefmt_cal_stdCdGrntStartDd();
        scwin.init_datefmt_cal_stdCdGrntEndDd();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf20000.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

