/**
 * @method
 * @name scwin.fn_Download
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_Download = async function () {
    await $c.win.alert("조회 내용이 없습니다.");
    return;
    if (($c.util.getComponent('cal_stdCdGrntStartDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntStartDd').getValue())) === '') {
        await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
        std_cd_grnt_start_dd.focus();
        return;
    } else {
        if (($c.util.getComponent('cal_stdCdGrntEndDd').getValue() == null ? '' : String($c.util.getComponent('cal_stdCdGrntEndDd').getValue())) === '') {
            await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
            std_cd_grnt_end_dd.focus();
            return;
        } else {
            let startD = $c.util.getComponent('cal_stdCdGrntStartDd').getValue();
            let startN = parseInt(startD.substr(4, 2), 10) - 1;
            let startT = new Date(startD.substr(0, 4), startN, startD.substr(6, 2));
            let endD = $c.util.getComponent('cal_stdCdGrntEndDd').getValue();
            let endN = parseInt(endD.substr(4, 2), 10) - 1;
            let endT = new Date(endD.substr(0, 4), endN, endD.substr(6, 2));
            let apDate = new Date(endT - 365 * 1000 * 60 * 60 * 24);
            if (apDate - startT > 0) {
                await $c.win.alert('다운로드는 일자를 1년 이내로 설정하여야\n\r사용이 가능합니다.');
                std_cd_grnt_start_dd.focus();
                return;
            }
        }
    }
    await $c.win.alert("다운로드는 데이터에 따라 몇초에서 몇분가량 소요될 수 있습니다.");
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_isurCd', ($c.util.getComponent("ipt_isurCd1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_isurCd'));
    ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_comNm', ($c.util.getComponent("ipt_comNm1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_comNm'));
    let frm = (document.JLDINF20000 || { elements: [] });
    if ($('#ipt_searchRadio10').is(":checked")) {
        frm.action = "/srch/srch.do?method=srchDownElsdlsList";
    } else {
        if ($('#ipt_searchRadio11').is(":checked")) {
            frm.action = "/srch/srch.do?method=srchDownElwList";
        } else {
            if ($('#ipt_searchRadio16').is(":checked")) {
                frm.action = "/srch/srch.do?method=srchDownEtnList";
            }
        }
    }
    frm.method = "post";
    frm.target = "iframeExcel";
    await scwin.tx_fn_Download();
};


