        std_cd_grnt_end_dd = '';
    }
    if ((std_cd_grnt_start_dd === "" && std_cd_grnt_end_dd === "") && searchRadio1 === "") {
        let now = new Date();
        let year = now.getFullYear();
        let mon = (now.getMonth() + 1) > 9 ? '' + (now.getMonth() + 1) : '0' + (now.getMonth() + 1);
        let day = now.getDate() > 9 ? '' + now.getDate() : '0' + now.getDate();
        let toDate = year + mon + day;
        let n = parseInt(toDate.substr(4, 2), 10) - 1;
        let st = new Date(toDate.substr(0, 4), n, toDate.substr(6, 2));
        let apDate = new Date(st - 30 * 1000 * 60 * 60 * 24);
        let startDate = apDate.getFullYear() + "" + fnLeg(apDate.getMonth() + 1) + "" + fnLeg(apDate.getDate());
        std_cd_grnt_start_dd = startDate;
        std_cd_grnt_end_dd = toDate;
