/**
 * @method
 * @name scwin.fn_search
 * @author Inswave
 * @date 2026. 09. 06
 * @param idx
 * @returns
 * @hidden N
*/
scwin.fn_search = async function (idx) {
    let gubun = $c.util.getComponent("dma_DownloadReq").get("gubunRadio");
    if (gubun === '1') {
        if (($c.util.getComponent('ipt_isurNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_isurNm1').getValue())) === '') {
            await $c.win.alert("한글종목명 및 표준코드을 입력하세요.");
            $c.util.getComponent("ipt_isurNm1").focus();
            return;
        }
        if ($c.str.getByteLength($c.util.getComponent('ipt_isurNm1').getValue()) <= 2) {
            await $c.win.alert("한글종목명 및 표준코드을 확인하세요");
            $c.util.getComponent("ipt_isurNm1").focus();
            return;
        }
        $('input[name=searchRadio][value=1]').attr("checked", true);
        ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_isurNm', ($c.util.getComponent("ipt_isurNm1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_isurNm'));
    } else {
        if (gubun === '2') {
            if (($c.util.getComponent('ipt_comNm1').getValue() == null ? '' : String($c.util.getComponent('ipt_comNm1').getValue())) === '') {
                await $c.win.alert("발행기관을 선택하세요.");
                return;
            }
            $('input[name=searchRadio][value=1]').attr("checked", true);
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_isurCd', ($c.util.getComponent("ipt_isurCd1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_isurCd'));
            ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_comNm', ($c.util.getComponent("ipt_comNm1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_comNm'));
        } else {
            if (gubun === '3') {
                ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_isurCd', ($c.util.getComponent("ipt_isurCd1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_isurCd'));
                ($c.util.getComponent('dma_hiddenStore') && $c.util.getComponent('dma_hiddenStore').set ? $c.util.getComponent('dma_hiddenStore').set('ipt_comNm', ($c.util.getComponent("ipt_comNm1").getValue() || '')) : console.warn('[sdd] hiddenStore 부재: ipt_comNm'));
            }
        }
    }
    let frm = (document.JLDINF20000 || { elements: [] });
    if (idx === '1') {
        $('input[name=pageIndex]').val("1");
    }
    frm.action = "/srch/srch.do?method=srchList";
    frm.target = "_self";
    blockLoading();
    await scwin.tx_fn_search();
    let dateGubun = $c.util.getComponent("dma_DownloadReq").get("searchDateRadio");
    if (dateGubun === "4") {
        scwin.fn_viewDownloadBtn("Y");
    } else {
        scwin.fn_viewDownloadBtn("N");
    }
};



